import { useEffect, useRef, useState } from "react";
import { useNavigate, Link } from "react-router-dom";
import { useAuth } from "@/App";
import { useReveal, prefersReducedMotion } from "@/lib/motion";
import BoundaryScene from "@/components/marketing/immersive/BoundaryScene";
import "./landing-immersive.css";

/* The immersive landing — one connected narrative, eight acts, one 3D object.
 *
 * Every claim on this page is regenerated by a make target in this repository
 * or read from contracts/deployments/46630.json. Nothing here is a price, no
 * metric is invented, and the testnet status is labelled as testnet. The 3D
 * canvas never carries essential text: labels, reasons and addresses all live
 * in semantic HTML. */

const EXPLORER = "https://explorer.testnet.chain.robinhood.com/address";

const DEPLOYMENTS = [
  ["IdentityRegistry", "0xBAd4cb2Ec6667674b2B61B1d4C8FFfbF7FE64040"],
  ["ReputationRegistry", "0xA565859472b507C539Fec560cc03D98a090108aB"],
  ["ValidationRegistry", "0x64DA01075D461Ef772E31fbE85fd74166852C72f"],
  ["StakeRegistry", "0x430fBFc8B5D77c7063725ECDd4c6E56CB952bd99"],
  ["IntentVault", "0x7778b9698cBA4Ff687Aa054c836F27b17640bF1c"],
  ["CreditMarket", "0xa542F94233783EB0Ac55a48695D9bd9224EE025C"],
  ["Settlement token (MockUSDC)", "0x6f92176d07634Be0D2E0334178fa23866aCcE802"],
];

const LAYERS = [
  {
    no: "L1", key: "identity", name: "Identity",
    body: "An agent is not a vibe. Registration is an ERC-8004 identity with a forfeitable bond, so a name you can slash stands behind every action.",
    reason: "UNKNOWN_AGENT / BANNED",
  },
  {
    no: "L2", key: "stake", name: "Stake",
    body: "Collateral in the game before an action is allowed. Below 100 USDC the gate closes and no amount of eloquence reopens it.",
    reason: "STAKE_TOO_LOW / SUSPENDED",
  },
  {
    no: "L3", key: "score", name: "Score",
    body: "A 0-100 accountability score computed from settled history with a public formula, so any two observers reach the same grade. Below 60, no execution.",
    reason: "SCORE_TOO_LOW",
  },
  {
    no: "L4", key: "intent", name: "Intent",
    body: "The plan is committed before execution: the action hash and its risk envelope (spend cap, allowed actions, deadline) are onchain first.",
    reason: "INTENT_NOT_COMMITTED / INTENT_ALREADY_EXECUTED",
  },
  {
    no: "L5", key: "time", name: "Time and scope",
    body: "A deadline and an exact envelope hash bound what was promised. Late execution, or execution of a different plan, is refused by the byte.",
    reason: "INTENT_EXPIRED / ENVELOPE_MISMATCH",
  },
];

const REFUSALS = [
  "UNKNOWN_AGENT", "BANNED", "SUSPENDED", "STAKE_TOO_LOW", "SCORE_TOO_LOW",
  "INTENT_NOT_COMMITTED", "INTENT_EXPIRED", "INTENT_ALREADY_EXECUTED", "ENVELOPE_MISMATCH",
];

const WORKFLOW = [
  { no: "01", name: "Commit", fn: "commitIntent", body: "The agent's plan and risk envelope are committed onchain before anything runs." },
  { no: "02", name: "Gate", fn: "checkGate", body: "One read answers five checks: identity, stake, score, intent, scope. View call, no gas." },
  { no: "03", name: "Execute", fn: "execute_fn", body: "Your code runs. Avaira never executes the action for you and never needs to." },
  { no: "04", name: "Attest", fn: "attestOutcome", body: "The outcome hash and its Merkle root are anchored, opening a 24-hour challenge window." },
  { no: "05", name: "Challenge", fn: "challengeDeviation", body: "Anyone with a proof can challenge a deviation. An upheld proof slashes stake." },
];

export default function Landing() {
  const { user } = useAuth();
  const navigate = useNavigate();
  const revealRoot = useReveal();

  /* scrollytelling state — refs, not re-renders, at 60fps */
  const trackRef = useRef(null);
  const explodedRef = useRef(0);
  const [layer, setLayer] = useState(0);

  useEffect(() => {
    const track = trackRef.current;
    if (!track || prefersReducedMotion()) return undefined;
    let raf = 0;
    const onScroll = () => {
      cancelAnimationFrame(raf);
      raf = requestAnimationFrame(() => {
        const r = track.getBoundingClientRect();
        const total = r.height - window.innerHeight;
        const p = Math.min(1, Math.max(0, -r.top / Math.max(1, total)));
        explodedRef.current = p;
        setLayer(Math.min(LAYERS.length - 1, Math.floor(p * LAYERS.length * 0.999)));
      });
    };
    window.addEventListener("scroll", onScroll, { passive: true });
    onScroll();
    return () => { window.removeEventListener("scroll", onScroll); cancelAnimationFrame(raf); };
  }, []);

  const go = (path) => () => navigate(user ? path : "/login");

  return (
    <div className="landing-immersive" data-testid="landing-page" ref={revealRoot}>
      <a href="#hero" className="sr-only focus:not-sr-only">Skip to content</a>

      {/* nav */}
      <nav className="imm-nav" aria-label="Avaira">
        <a className="imm-wordmark" href="#hero">AVaira<span>.</span></a>
        <div className="imm-nav-links">
          <a href="#boundary">The boundary</a>
          <a href="#execution">Execution</a>
          <a href="#evidence">Evidence</a>
          <a href="#architecture">Architecture</a>
        </div>
        <div style={{ display: "flex", gap: "0.7rem", alignItems: "center" }}>
          {user ? (
            <button type="button" className="imm-btn imm-btn-primary" data-testid="launch-protocol-btn" onClick={go("/dashboard")}>
              Open console
            </button>
          ) : (
            <>
              <button type="button" className="imm-btn imm-btn-ghost" data-testid="nav-login-btn" onClick={go("/login")}>
                Sign in
              </button>
              <button type="button" className="imm-btn imm-btn-primary" data-testid="launch-protocol-btn" onClick={go("/dashboard")}>
                Open console
              </button>
            </>
          )}
        </div>
      </nav>

      {/* Act I — the thesis */}
      <header className="imm-hero" id="hero" data-testid="hero-section">
        <div className="imm-hero-canvas">
          <BoundaryScene exploded={0} />
        </div>
        <div className="imm-hero-copy">
          <p className="imm-label" style={{ marginBottom: "1.4rem" }}>Onchain accountability for AI agents</p>
          <h1 className="imm-display">
            An agent proposes.
            <br />
            <em>Avaira</em> verifies.
          </h1>
          <p className="imm-lead" style={{ margin: "1.6rem 0 2rem" }}>
            Every action is committed before it runs, gated against identity, stake
            and score, and settled with evidence anyone can re-read onchain.
            Built for Robinhood Chain.
          </p>
          <div style={{ display: "flex", gap: "0.8rem", flexWrap: "wrap" }}>
            <Link className="imm-btn imm-btn-primary" data-testid="hero-launch-btn" to="/gate">
              Explore the gate
            </Link>
            {user ? (
              <button type="button" className="imm-btn imm-btn-ghost" onClick={go("/dashboard")}>
                Open console
              </button>
            ) : (
              <button type="button" className="imm-btn imm-btn-ghost" data-testid="hero-login-btn" onClick={go("/login")}>
                Sign in
              </button>
            )}
          </div>
        </div>
        <p className="imm-label imm-scrollhint">Scroll — the boundary explains itself</p>
      </header>

      {/* Act II — the problem */}
      <section className="imm-act" data-testid="problem-section" aria-labelledby="problem-h">
        <div className="imm-act-head">
          <p className="imm-label">The problem</p>
          <h2 className="imm-h2" id="problem-h" data-reveal>
            Between a proposal and an action there is usually nothing.
          </h2>
          <p className="imm-lead" data-reveal>
            An agent asks to move funds, call a tool, spend a budget. In most
            stacks the request goes straight through. The prompt is the only
            policy, the logs are the only evidence, and both can be edited after
            the fact by the same party that ran the action.
          </p>
          <p className="imm-body" data-reveal>
            Avaira makes the gap a boundary: a place where authorization is
            decided by contracts, not by confidence, and where the record of the
            decision cannot be rewritten by anyone, including us.
          </p>
        </div>
      </section>

      {/* Act III — the boundary (scrollytelling) */}
      <section className="imm-boundary" id="boundary" data-testid="boundary-section" aria-labelledby="boundary-h">
        <h2 className="sr-only" id="boundary-h">The execution boundary, layer by layer</h2>
        <div className="imm-boundary-track" ref={trackRef}>
          <div className="imm-boundary-stage">
            <div className="imm-boundary-canvas">
              <BoundaryScene exploded={explodedRef} />
            </div>
            <div className="imm-progress" aria-hidden="true">
              {LAYERS.map((l, i) => (
                <span key={l.key} className={`imm-progress-dot${i === layer ? " imm-dot-on" : ""}`} />
              ))}
            </div>
            {LAYERS.map((l, i) => (
              <article
                key={l.key}
                className={`imm-layer${i === layer ? " imm-layer-on" : ""}`}
                data-testid={`boundary-act-${l.key}`}
                aria-hidden={i === layer ? undefined : "true"}
              >
                <p className="imm-label">{`Gate layer ${l.no}`}</p>
                <h3>{l.name}</h3>
                <p className="imm-body">{l.body}</p>
                <p className="imm-reason">{`reverts: ${l.reason}`}</p>
              </article>
            ))}

          </div>
        </div>
      </section>

      {/* Act IV — the execution */}
      <section className="imm-act" id="execution" data-testid="workflow-section" aria-labelledby="execution-h">
        <div className="imm-act-head">
          <p className="imm-label">The execution</p>
          <h2 className="imm-h2" id="execution-h" data-reveal>
            Five functions, in the order the chain enforces them.
          </h2>
          <p className="imm-lead" data-reveal>
            This is the whole lifecycle. Each step is a named function in the
            deployed vault, and the SDK wraps all of them.
          </p>
        </div>
        <div className="imm-pipeline">
          {WORKFLOW.map((s) => (
            <div key={s.no} className="imm-step" data-reveal>
              <p className="imm-step-no">{`Step ${s.no}`}</p>
              <h3>{s.name}</h3>
              <p>{s.body}</p>
              <p><code>{s.fn}</code></p>
            </div>
          ))}
        </div>
      </section>

      {/* Act V — the decision */}
      <section className="imm-act" data-testid="decision-section" aria-labelledby="decision-h">
        <div className="imm-act-head">
          <p className="imm-label">The decision</p>
          <h2 className="imm-h2" id="decision-h" data-reveal>
            One view call. Two outcomes. Nine ways to be refused.
          </h2>
        </div>
        <div className="imm-decision">
          <div className="imm-verdict imm-allowed" data-reveal>
            <p className="imm-label" style={{ color: "var(--imm-lime)" }}>Allowed path</p>
            <h3>Permitted</h3>
            <p className="imm-body">
              Every layer passes: a registered identity, stake above minimum, a
              score above 60, a committed intent inside its deadline, matching
              the exact envelope hash. The action runs, the outcome is attested,
              and the challenge window opens.
            </p>
            <p className="imm-reason" style={{ marginTop: "1.2rem" }}>reason: allowed</p>
          </div>
          <div className="imm-verdict imm-rejected" data-reveal>
            <p className="imm-label">Refused path</p>
            <h3>Refused</h3>
            <p className="imm-body">
              Any single failing layer closes the gate before the action runs.
              The refusal is a named, onchain-readable reason, not a 500 from a
              proxy:
            </p>
            <ul className="imm-reasons">
              {REFUSALS.map((r) => (
                <li key={r}>{r}</li>
              ))}
            </ul>
            <p className="imm-body" style={{ marginTop: "1.2rem", fontSize: "0.78rem" }}>
              The examples above are illustrative walkthroughs of the deployed
              contracts, not live transactions.
            </p>
          </div>
        </div>
      </section>

      {/* Act VI — the evidence */}
      <section className="imm-act" id="evidence" data-testid="evidence-section" aria-labelledby="evidence-h">
        <div className="imm-act-head">
          <p className="imm-label">The evidence</p>
          <h2 className="imm-h2" id="evidence-h" data-reveal>
            Deployed, wired, and verifiable from the explorer.
          </h2>
          <p className="imm-lead" data-reveal>
            {`Robinhood Chain testnet, chain id 46630, deployed 2026-10-24.
              Every address below is live and liveness-checked by a make target
              in the repository. Testnet means testnet: this is not a mainnet
              launch claim.`}
          </p>
        </div>
        <div style={{ overflowX: "auto" }} data-reveal>
          <table className="imm-table" data-testid="evidence-table">
            <caption className="sr-only">Avaira contracts deployed on Robinhood Chain testnet</caption>
            <thead>
              <tr>
                <th scope="col">Contract</th>
                <th scope="col">Address (chain 46630)</th>
                <th scope="col">Explorer</th>
              </tr>
            </thead>
            <tbody>
              {DEPLOYMENTS.map(([name, addr]) => (
                <tr key={addr}>
                  <td>{name}</td>
                  <td className="imm-addr">{addr}</td>
                  <td><a href={`${EXPLORER}/${addr}`}>view</a></td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        <div className="imm-receipts" data-reveal>
          <div className="imm-receipt">
            <p className="imm-label">Foundry tests</p>
            <strong>157</strong>
            <span>passing, 0 skipped, run locally</span>
          </div>
          <div className="imm-receipt">
            <p className="imm-label">Fuzz campaign</p>
            <strong>2000</strong>
            <span>sequences, 12 invariants, 0 violations</span>
          </div>
          <div className="imm-receipt">
            <p className="imm-label">Red-team findings</p>
            <strong>15</strong>
            <span>each with replay command and status</span>
          </div>
          <div className="imm-receipt">
            <p className="imm-label">Parity vectors</p>
            <strong>42</strong>
            <span>identical on-chain, Python, TypeScript</span>
          </div>
        </div>
      </section>

      {/* Act VII — the architecture */}
      <section className="imm-act" id="architecture" data-testid="architecture-section" aria-labelledby="arch-h">
        <div className="imm-act-head">
          <p className="imm-label">The architecture</p>
          <h2 className="imm-h2" id="arch-h" data-reveal>
            Six contracts, two services, two SDKs, one public formula.
          </h2>
        </div>
        <div className="imm-stack" data-reveal>
          <div className="imm-stack-row">
            <h3>Protocol contracts</h3>
            <p>Identity, reputation, validation, stake, intent vault, credit market, plus the settlement token. Foundry, 126 onchain test functions, machine-checked invariants.</p>
            <a href="https://github.com/ranaalyan1/avaira.xyz">source</a>
          </div>
          <div className="imm-stack-row">
            <h3>Scorer service</h3>
            <p>The 0-100 score as pure functions, with grade parity pinned against the on-chain table by test.</p>
            <a href="https://github.com/ranaalyan1/avaira.xyz/tree/main/services/scorer">source</a>
          </div>
          <div className="imm-stack-row">
            <h3>Gateway service</h3>
            <p>The offchain half: HMAC-signed requests, single-use nonces, a per-agent circuit breaker, and one read-only gate call. It never broadcasts.</p>
            <a href="https://github.com/ranaalyan1/avaira.xyz/tree/main/services/gateway">source</a>
          </div>
          <div className="imm-stack-row">
            <h3>SDKs</h3>
            <p>TypeScript and Python, sharing the same 42 canonical parity vectors as the contracts.</p>
            <a href="https://github.com/ranaalyan1/avaira.xyz/tree/main/sdk">source</a>
          </div>
          <div className="imm-stack-row">
            <h3>Audit package</h3>
            <p>Threat model, invariants, risk register and 15 findings with replay commands. Self-adversarial, labelled as such; not a third-party audit.</p>
            <a href="https://github.com/ranaalyan1/avaira.xyz/tree/main/audit">read</a>
          </div>
        </div>
      </section>

      {/* Act VIII — the invitation */}
      <section className="imm-cta" data-testid="cta-section" aria-labelledby="cta-h">
        <div>
          <p className="imm-label">The invitation</p>
          <h2 className="imm-h2" id="cta-h" style={{ margin: "0.8rem 0 1rem" }} data-reveal>
            Build agents that can prove what they did.
          </h2>
          <p className="imm-lead" style={{ margin: "0 auto" }} data-reveal>
            The protocol, the tests, the audit package and the deployment record
            are all public. Read the mechanics before you trust a single word
            of this page, that is the point.
          </p>
        </div>
        <div className="imm-cta-actions" data-reveal>
          <Link className="imm-btn imm-btn-primary" data-testid="cta-launch-btn" to="/gate">
            See the gate mechanics
          </Link>
          <a className="imm-btn imm-btn-ghost" href="https://github.com/ranaalyan1/avaira.xyz">
            Read the source
          </a>
          <Link className="imm-btn imm-btn-ghost" to="/docs">
            Integrate the SDK
          </Link>
        </div>
      </section>

      <footer className="imm-foot">
        <p className="imm-footnote">
          Avaira is an independent project building on the public Robinhood
          Chain network. It is not affiliated with Robinhood. Contract
          addresses on this page refer to the public testnet, chain id 46630.
        </p>
        <div style={{ display: "flex", gap: "1.4rem" }}>
          <Link to="/evidence">Evidence</Link>
          <Link to="/docs">Docs</Link>
          <a href="https://github.com/ranaalyan1/avaira.xyz">GitHub</a>
        </div>
      </footer>
    </div>
  );
}
